/**
 * Validates all fields in Token according to their annotations.
 * @throws {BlueErr} if validation fails
 */
export function validateToken(m: Token | undefined): void {
  if (!m) {
    return;
  }

  // Validate signature (assert_base64)
  if (m.signature) {
    const base64Regex = /^[A-Za-z0-9+/]*={0,2}$/;
    if (!base64Regex.test(m.signature)) {
      throw newErrMissingInvalidData(
        undefined,
        `field signature must be valid base64`,
      );
    }
  }

  // Validate base64 (assert_base64)
  if (m.base64) {
    const base64Regex = /^[A-Za-z0-9+/]*={0,2}$/;
    if (!base64Regex.test(m.base64)) {
      throw newErrMissingInvalidData(
        undefined,
        `field base64 must be valid base64`,
      );
    }
  }

  // Validate signature (default max size: 32768 bytes)
  if (m.signature && new TextEncoder().encode(m.signature).length > 32768) {
    throw newErrMissingInvalidData(
      undefined,
      `field signature exceeds max size of 32768 bytes, got: ${new TextEncoder().encode(m.signature).length}`,
    );
  }

  // Validate base64 (default max size: 32768 bytes)
  if (m.base64 && new TextEncoder().encode(m.base64).length > 32768) {
    throw newErrMissingInvalidData(
      undefined,
      `field base64 exceeds max size of 32768 bytes, got: ${new TextEncoder().encode(m.base64).length}`,
    );
  }
}
/**
 * Validates all fields in Exchange according to their annotations.
 * @throws {BlueErr} if validation fails
 */
export function validateExchange(m: Exchange | undefined): void {
  if (!m) {
    return;
  }

  // Validate expiresIn (assert_gt: 0)
  if (m.expiresIn !== undefined && m.expiresIn <= 0) {
    throw newErrMissingInvalidData(
      undefined,
      `field expiresIn must be > 0, got: ${m.expiresIn}`,
    );
  }

  // Validate error (default max size: 32768 bytes)
  if (m.error && new TextEncoder().encode(m.error).length > 32768) {
    throw newErrMissingInvalidData(
      undefined,
      `field error exceeds max size of 32768 bytes, got: ${new TextEncoder().encode(m.error).length}`,
    );
  }

  // Validate errorDescription (default max size: 32768 bytes)
  if (
    m.errorDescription &&
    new TextEncoder().encode(m.errorDescription).length > 32768
  ) {
    throw newErrMissingInvalidData(
      undefined,
      `field errorDescription exceeds max size of 32768 bytes, got: ${new TextEncoder().encode(m.errorDescription).length}`,
    );
  }

  // Validate accessToken (default max size: 32768 bytes)
  if (m.accessToken && new TextEncoder().encode(m.accessToken).length > 32768) {
    throw newErrMissingInvalidData(
      undefined,
      `field accessToken exceeds max size of 32768 bytes, got: ${new TextEncoder().encode(m.accessToken).length}`,
    );
  }

  // Validate tokenType (default max size: 32768 bytes)
  if (m.tokenType && new TextEncoder().encode(m.tokenType).length > 32768) {
    throw newErrMissingInvalidData(
      undefined,
      `field tokenType exceeds max size of 32768 bytes, got: ${new TextEncoder().encode(m.tokenType).length}`,
    );
  }

  // Validate scope (default max size: 32768 bytes)
  if (m.scope && new TextEncoder().encode(m.scope).length > 32768) {
    throw newErrMissingInvalidData(
      undefined,
      `field scope exceeds max size of 32768 bytes, got: ${new TextEncoder().encode(m.scope).length}`,
    );
  }

  // Validate idToken (default max size: 32768 bytes)
  if (m.idToken && new TextEncoder().encode(m.idToken).length > 32768) {
    throw newErrMissingInvalidData(
      undefined,
      `field idToken exceeds max size of 32768 bytes, got: ${new TextEncoder().encode(m.idToken).length}`,
    );
  }
}
/**
 * Validates all fields in TokenRequestParams according to their annotations.
 * @throws {BlueErr} if validation fails
 */
export function validateTokenRequestParams(
  m: TokenRequestParams | undefined,
): void {
  if (!m) {
    return;
  }

  // Validate clientId (assert_min_length: 1)
  if (m.clientId && m.clientId.length < 1) {
    throw newErrMissingInvalidData(
      undefined,
      `field clientId must have length >= 1, got: ${m.clientId.length}`,
    );
  }

  // Validate clientId (default max size: 32768 bytes)
  if (m.clientId && new TextEncoder().encode(m.clientId).length > 32768) {
    throw newErrMissingInvalidData(
      undefined,
      `field clientId exceeds max size of 32768 bytes, got: ${new TextEncoder().encode(m.clientId).length}`,
    );
  }

  // Validate requestedClientId (default max size: 32768 bytes)
  if (
    m.requestedClientId &&
    new TextEncoder().encode(m.requestedClientId).length > 32768
  ) {
    throw newErrMissingInvalidData(
      undefined,
      `field requestedClientId exceeds max size of 32768 bytes, got: ${new TextEncoder().encode(m.requestedClientId).length}`,
    );
  }

  // Validate aud (default max size: 32768 bytes)
  if (m.aud && new TextEncoder().encode(m.aud).length > 32768) {
    throw newErrMissingInvalidData(
      undefined,
      `field aud exceeds max size of 32768 bytes, got: ${new TextEncoder().encode(m.aud).length}`,
    );
  }

  // Validate storeCode (default max size: 32768 bytes)
  if (m.storeCode && new TextEncoder().encode(m.storeCode).length > 32768) {
    throw newErrMissingInvalidData(
      undefined,
      `field storeCode exceeds max size of 32768 bytes, got: ${new TextEncoder().encode(m.storeCode).length}`,
    );
  }

  // Validate code (default max size: 32768 bytes)
  if (m.code && new TextEncoder().encode(m.code).length > 32768) {
    throw newErrMissingInvalidData(
      undefined,
      `field code exceeds max size of 32768 bytes, got: ${new TextEncoder().encode(m.code).length}`,
    );
  }

  // Validate state (default max size: 32768 bytes)
  if (m.state && new TextEncoder().encode(m.state).length > 32768) {
    throw newErrMissingInvalidData(
      undefined,
      `field state exceeds max size of 32768 bytes, got: ${new TextEncoder().encode(m.state).length}`,
    );
  }

  // Validate redirectUri (default max size: 32768 bytes)
  if (m.redirectUri && new TextEncoder().encode(m.redirectUri).length > 32768) {
    throw newErrMissingInvalidData(
      undefined,
      `field redirectUri exceeds max size of 32768 bytes, got: ${new TextEncoder().encode(m.redirectUri).length}`,
    );
  }

  // Validate verifier (default max size: 32768 bytes)
  if (m.verifier && new TextEncoder().encode(m.verifier).length > 32768) {
    throw newErrMissingInvalidData(
      undefined,
      `field verifier exceeds max size of 32768 bytes, got: ${new TextEncoder().encode(m.verifier).length}`,
    );
  }
}

// ============================================================
// FromMap / ToMap Helpers
// ============================================================
/** * Creates a TokenRequestParams from a map of URL parameters.
 * The parameter keys are validated against TokenParamKey enum values.
 * Unknown parameter keys are silently ignored (non-strict mode).
 */
export function tokenRequestParamsFromMap(
  params: Record<string, string>,
): TokenRequestParams {
  const result = create(TokenRequestParamsSchema, {});
  for (const [key, value] of Object.entries(params)) {
    const paramKey = parseTokenParamKey(key);
    if (paramKey === undefined) {
      continue; // Ignore unknown keys in non-strict mode
    }
    switch (paramKey) {
      case TokenParamKey.CLIENT_ID:
        result.clientId = value;
        break;
      case TokenParamKey.AUD:
        result.aud = value;
        break;
      case TokenParamKey.EXP:
        const floatVal = parseFloat(value);
        if (!isNaN(floatVal)) {
          result.exp = floatVal;
        }
        break;
      case TokenParamKey.INCLUDE_CLAIMS:
        if (value) {
          result.includeClaims = value.split(",");
        }
        break;
      case TokenParamKey.EXCLUDE_CLAIMS:
        if (value) {
          result.excludeClaims = value.split(",");
        }
        break;
      case TokenParamKey.STORE_CODE:
        result.storeCode = value;
        break;
      case TokenParamKey.CODE:
        result.code = value;
        break;
      case TokenParamKey.STATE:
        result.state = value;
        break;
      case TokenParamKey.REDIRECT_URI:
        result.redirectUri = value;
        break;
      case TokenParamKey.VERIFIER:
        result.verifier = value;
        break;
      case TokenParamKey.GRANT_TYPE:
        result.grantType = parseGrantType(value);
        break;
    }
  }
  return result;
}
/** * Converts a TokenRequestParams to a map of URL parameters.
 * The map keys are the json_return_value of TokenParamKey enum values.
 * Only non-empty fields are included in the map.
 */
export function tokenRequestParamsToMap(
  m: TokenRequestParams,
): Record<string, string> {
  const result: Record<string, string> = {};
  if (m.clientId) {
    result["client_id"] = m.clientId;
  }
  if (m.aud) {
    result["aud"] = m.aud;
  }
  if (m.exp !== undefined && m.exp !== null) {
    result["exp"] = m.exp.toString();
  }
  if (m.includeClaims && m.includeClaims.length > 0) {
    result["include_claims"] = m.includeClaims.join(",");
  }
  if (m.excludeClaims && m.excludeClaims.length > 0) {
    result["exclude_claims"] = m.excludeClaims.join(",");
  }
  if (m.storeCode) {
    result["store_code"] = m.storeCode;
  }
  if (m.code) {
    result["code"] = m.code;
  }
  if (m.state) {
    result["state"] = m.state;
  }
  if (m.redirectUri) {
    result["redirect_uri"] = m.redirectUri;
  }
  if (m.verifier) {
    result["verifier"] = m.verifier;
  }
  if (m.grantType) {
    result["grant_type"] = grantTypeToString(m.grantType);
  }
  return result;
}

// ============================================================
// Merge: Token
// ============================================================
/** Fills zero-valued fields in dst from src. dst takes precedence. */
export function mergeToken(dst: Token, src: Token): void {
  if (!dst.payload && src.payload) {
    dst.payload = src.payload;
  }
  if (dst.signature === "") {
    dst.signature = src.signature;
  }
  if (dst.base64 === "") {
    dst.base64 = src.base64;
  }
}
// ============================================================
// Merge: Exchange
// ============================================================
/** Fills zero-valued fields in dst from src. dst takes precedence. */
export function mergeExchange(dst: Exchange, src: Exchange): void {
  if (dst.error === "") {
    dst.error = src.error;
  }
  if (dst.errorDescription === "") {
    dst.errorDescription = src.errorDescription;
  }
  if (dst.accessToken === "") {
    dst.accessToken = src.accessToken;
  }
  if (dst.tokenType === "") {
    dst.tokenType = src.tokenType;
  }
  if (dst.expiresIn === 0) {
    dst.expiresIn = src.expiresIn;
  }
  if (dst.scope === "") {
    dst.scope = src.scope;
  }
  if (dst.idToken === "") {
    dst.idToken = src.idToken;
  }
}
// ============================================================
// Merge: TokenRequestParams
// ============================================================
/** Fills zero-valued fields in dst from src. dst takes precedence. */
export function mergeTokenRequestParams(
  dst: TokenRequestParams,
  src: TokenRequestParams,
): void {
  if (dst.clientId === "") {
    dst.clientId = src.clientId;
  }
  if (dst.requestedClientId === "") {
    dst.requestedClientId = src.requestedClientId;
  }
  if (dst.aud === "") {
    dst.aud = src.aud;
  }
  if (dst.exp === 0) {
    dst.exp = src.exp;
  }
  if (dst.includeClaims.length === 0) {
    dst.includeClaims = src.includeClaims;
  }
  if (dst.excludeClaims.length === 0) {
    dst.excludeClaims = src.excludeClaims;
  }
  if (dst.storeCode === "") {
    dst.storeCode = src.storeCode;
  }
  if (dst.code === "") {
    dst.code = src.code;
  }
  if (dst.state === "") {
    dst.state = src.state;
  }
  if (dst.redirectUri === "") {
    dst.redirectUri = src.redirectUri;
  }
  if (dst.verifier === "") {
    dst.verifier = src.verifier;
  }
  if (dst.grantType === 0) {
    dst.grantType = src.grantType;
  }
}
